// Offline support: saves every file of the app on the phone the first time it opens.
// Generated by scripts/build.py; the version changes whenever any file changes.
const VERSION = 'leafcheck-59be959526';
const FILES = ['./', 'css/app.css', 'data/cards.json', 'data/game.json', 'data/model.json', 'data/photos.json', 'fonts/atkinson-hyperlegible-latin-400-normal.woff2', 'fonts/atkinson-hyperlegible-latin-700-normal.woff2', 'fonts/bitter-latin-600-normal.woff2', 'fonts/bitter-latin-700-normal.woff2', 'fonts/noto-sans-devanagari-devanagari-400-normal.woff2', 'fonts/noto-sans-devanagari-devanagari-700-normal.woff2', 'fonts/noto-serif-devanagari-devanagari-600-normal.woff2', 'fonts/noto-serif-devanagari-devanagari-700-normal.woff2', 'icons/apple-touch-icon.png', 'icons/icon-192.png', 'icons/icon-512.png', 'icons/maskable-512.png', 'index.html', 'js/app.js', 'js/i18n.js', 'js/model.js', 'manifest.webmanifest', 'model/group1-shard1of1.bin', 'model/model.json', 'vendor/tf-backend-wasm.min.js', 'vendor/tf.min.js', 'vendor/tfjs-backend-wasm-simd.wasm', 'vendor/tfjs-backend-wasm.wasm'];

self.addEventListener('install', event => {
  event.waitUntil(caches.open(VERSION).then(cache => cache.addAll(FILES)).then(() => self.skipWaiting()));
});

self.addEventListener('activate', event => {
  event.waitUntil(
    caches.keys()
      .then(keys => Promise.all(keys.filter(k => k !== VERSION).map(k => caches.delete(k))))
      .then(() => self.clients.claim())
      .then(() => self.clients.matchAll())
      .then(clients => clients.forEach(c => c.postMessage('cached')))
  );
});

// Big files (model, runtime, fonts, photos) come from the phone's copy first.
// Small text files (page, code, advice) try the internet for 2.5 seconds first, so edits show up,
// and fall back to the saved copy when there is no connection.
const BIG = /\.(bin|wasm|woff2|png)$|photos\.json$|tf\.min\.js$|tf-backend-wasm\.min\.js$/;

function fromNetwork(request) {
  return fetch(request).then(response => {
    if (response.ok && new URL(request.url).origin === location.origin) {
      const copy = response.clone();
      caches.open(VERSION).then(cache => cache.put(request, copy));
    }
    return response;
  });
}

self.addEventListener('fetch', event => {
  const request = event.request;
  if (request.method !== 'GET' || new URL(request.url).origin !== location.origin) return;
  if (BIG.test(new URL(request.url).pathname)) {
    event.respondWith(caches.match(request, { ignoreSearch: true }).then(hit => hit || fromNetwork(request)));
    return;
  }
  event.respondWith(new Promise(resolve => {
    let done = false;
    const fallback = () => caches.match(request, { ignoreSearch: true }).then(hit => { if (hit && !done) { done = true; resolve(hit); } return hit; });
    const timer = setTimeout(fallback, 2500);
    fromNetwork(request)
      .then(response => { clearTimeout(timer); if (!done) { done = true; resolve(response); } })
      .catch(() => { clearTimeout(timer); fallback().then(hit => { if (!hit && !done) { done = true; resolve(Response.error()); } }); });
  }));
});
